# Untrapped Ultra Mode - self-updating, self-healing system diagnostic
# The diagnostic MAY update/repair Untrapped-owned components only.
# It NEVER changes Windows Firewall/WFP/DNS/routes/Hosts/proxy/adapters/VPN/override policy.
$ErrorActionPreference='SilentlyContinue'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
$Parent=Split-Path -Parent $Root
$ReportPath=Join-Path $Root 'diagnostic-latest.txt'
$RepoBase='https://raw.githubusercontent.com/mehdishah5372-hue/Untrapped/main/'
$StatusPath=$MyInvocation.MyCommand.Path
$SelfRepairPath=Join-Path $Root 'self-repair.ps1'
$ExtensionFiles=@('manifest.json','background.js','content.js','popup.html','popup.js','bootstrap.bundle.min.js')
$CoreFiles=@('config.json','packet-filter.ps1','ultra-mode.ps1','status-untrapped.ps1','self-repair.ps1')
$Lines=New-Object 'System.Collections.Generic.List[string]'
$Problems=New-Object 'System.Collections.Generic.List[string]'
$Status=New-Object 'System.Collections.Generic.List[string]'
$RepairRan=$false
$UpdateState='UNKNOWN'
function Trace([string]$Stage,[string]$Message){$line='['+(Get-Date -Format 'HH:mm:ss')+'] ['+$Stage+'] '+$Message;Write-Host $line;[void]$Lines.Add($line)}
function Problem([string]$Message){if($Message -and -not($Problems -contains $Message)){[void]$Problems.Add($Message)}}
function StatusLine([string]$Name,[string]$Value){$line=('{0}: {1}' -f $Name,$Value);[void]$Status.Add($line);Trace 'STATUS' $line}
function Hash([byte[]]$b){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function DownloadBytes([string]$path){Trace 'GITHUB' ('DOWNLOAD '+$path);$r=Invoke-WebRequest -Uri ($RepoBase+$path+'?cb='+[DateTime]::UtcNow.Ticks) -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop;return [Text.Encoding]::UTF8.GetBytes([string]$r.Content)}
function Valid([string]$name,[byte[]]$b){try{$t=[Text.Encoding]::UTF8.GetString($b);if($b.Length -lt 20){throw 'File is unexpectedly small.'};if($name -match '\.ps1$'){[void][scriptblock]::Create($t)}elseif($name -match '\.json$'){$null=$t|ConvertFrom-Json};return $true}catch{Trace 'VALIDATE' ('FAILED '+$name+': '+$_.Exception.Message);return $false}}
function Canonical([string]$remote){try{$b=DownloadBytes $remote;if(-not(Valid $remote $b)){throw 'Canonical validation failed.'};return $b}catch{Trace 'GITHUB' ('FAILED '+$remote+': '+$_.Exception.Message);return $null}}
function UpdateOne([string]$local,[string]$remote,[string]$label){if(-not(Test-Path -LiteralPath $local)){Trace 'UPDATE' ('MISSING '+$label);return $false};$remoteBytes=Canonical $remote;if($null -eq $remoteBytes){return $false};try{$localBytes=[IO.File]::ReadAllBytes($local)}catch{return $false};if((Hash $localBytes) -eq (Hash $remoteBytes)){Trace 'UPDATE' ('CURRENT '+$label);return $false};$backup=$local+'.pre-update-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.bak';try{Copy-Item -LiteralPath $local -Destination $backup -Force;Trace 'UPDATE' ('BACKUP '+$backup);$tmp=$local+'.update-'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllBytes($tmp,$remoteBytes);if((Hash ([IO.File]::ReadAllBytes($tmp))) -ne (Hash $remoteBytes)){throw 'Temporary verification failed.'};Move-Item -LiteralPath $tmp -Destination $local -Force;if((Hash ([IO.File]::ReadAllBytes($local))) -ne (Hash $remoteBytes)){throw 'Post-update verification failed.'};Trace 'UPDATE' ('UPDATED '+$label);return $true}catch{Trace 'UPDATE' ('FAILED '+$label+': '+$_.Exception.Message);return $false}}
function Https([string]$HostName){try{return [bool](Test-NetConnection -ComputerName $HostName -Port 443 -WarningAction SilentlyContinue).TcpTestSucceeded}catch{return $false}}
function Find-BraveUntrapped{$out=@();$ud=Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data';if(-not(Test-Path -LiteralPath $ud)){return @()};foreach($p in @(Get-ChildItem -LiteralPath $ud -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name -eq 'Default' -or $_.Name -like 'Profile *'})){ $ed=Join-Path $p.FullName 'Extensions';if(-not(Test-Path -LiteralPath $ed)){continue};foreach($id in @(Get-ChildItem -LiteralPath $ed -Directory -ErrorAction SilentlyContinue)){foreach($v in @(Get-ChildItem -LiteralPath $id.FullName -Directory -ErrorAction SilentlyContinue)){ $m=Join-Path $v.FullName 'manifest.json';if(Test-Path -LiteralPath $m){try{if(([string](Get-Content -LiteralPath $m -Raw|ConvertFrom-Json).name)-eq 'Untrapped'){$out+=$v.FullName}}catch{}}}}};return @($out|Sort-Object -Unique)}
function Invoke-Repair{if(-not(Test-Path -LiteralPath $SelfRepairPath)){Trace 'AUTO-REPAIR' 'self-repair.ps1 is missing.';return $false};Trace 'AUTO-REPAIR' 'Invoking bounded Untrapped self-repair.';$p=Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$SelfRepairPath) -WorkingDirectory $Root -Verb RunAs -WindowStyle Normal -PassThru -ErrorAction SilentlyContinue;if($null -eq $p){Trace 'AUTO-REPAIR' 'Could not start self-repair.';return $false};$p.WaitForExit();Trace 'AUTO-REPAIR' ('Process exit code: '+$p.ExitCode);return ($p.ExitCode -eq 0)}
function RunChecks{Trace 'POLICY' 'Reading configuration, schedule and override.';$config=$null;$scheduled=$false;$override=$false;try{$config=Get-Content -LiteralPath (Join-Path $Root 'config.json') -Raw|ConvertFrom-Json;$start=[TimeSpan]::Parse([string]$config.start);$end=[TimeSpan]::Parse([string]$config.end);$now=(Get-Date).TimeOfDay;if($start -eq $end){$inWindow=$true}elseif($start -lt $end){$inWindow=($now -ge $start -and $now -lt $end)}else{$inWindow=($now -ge $start -or $now -lt $end)};$of=Join-Path $Root 'override-until.txt';if(Test-Path -LiteralPath $of){try{$until=[DateTime]::Parse((Get-Content -LiteralPath $of -Raw)).ToUniversalTime();$override=([DateTime]::UtcNow -lt $until)}catch{Problem 'Override file exists but is unreadable.'}};$scheduled=[bool]($config.enabled -and $inWindow -and -not $override);StatusLine 'Policy enabled' $config.enabled;StatusLine 'Schedule' ($config.start+' - '+$config.end);StatusLine 'Scheduled blocking active' $scheduled;StatusLine 'Override active' $override}catch{Problem 'Config is invalid or unreadable.'};Trace 'POLICY' 'Testing actual target reachability.';$yt=Https 'www.youtube.com';$chat=Https 'chatgpt.com';$crush=Https 'www.crushon.ai';$expected=-not $scheduled;StatusLine 'YouTube actual' $(if($yt){'REACHABLE'}else{'BLOCKED'});StatusLine 'ChatGPT actual' $(if($chat){'REACHABLE'}else{'BLOCKED'});StatusLine 'CrushOn actual' $(if($crush){'REACHABLE'}else{'BLOCKED'});if($yt -ne $expected){Problem 'YouTube does not match configured policy.'};if($chat -ne $expected){Problem 'ChatGPT does not match configured policy.'};if($crush){Problem 'CrushOn is reachable despite always-block policy.'};Trace 'CORE' 'Checking processes and canonical source.';$packet=@(Get-CimInstance Win32_Process|Where-Object{$_.CommandLine -like '*packet-filter.ps1*'});$control=@(Get-CimInstance Win32_Process|Where-Object{$_.CommandLine -like '*ultra-mode.ps1*'});$coreBad=@();$missing=@();foreach($f in $CoreFiles){$p=Join-Path $Root $f;if(-not(Test-Path -LiteralPath $p)){$missing+=$f}elseif(-not(SameCanonical $f $p)){$coreBad+=$f}};foreach($f in @('WinDivert.dll','WinDivert64.sys')){if(-not(Test-Path -LiteralPath (Join-Path $Root $f))){$missing+=$f}};StatusLine 'Packet filter process' $(if($packet.Count){'RUNNING'}else{'STOPPED'});StatusLine 'Control plane process' $(if($control.Count){'RUNNING'}else{'STOPPED'});StatusLine 'Core canonical mismatches' $(if($coreBad.Count){$coreBad -join ', '}else{'NONE'});StatusLine 'Missing required files' $(if($missing.Count){$missing -join ', '}else{'NONE'});if(-not$packet.Count){Problem 'Packet filter is not running.'};if(-not$control.Count){Problem 'Control plane is not running.'};if($missing.Count){Problem ('Required Untrapped files missing: '+($missing -join ', '))};if($coreBad.Count){Problem ('Untrapped core differs from canonical GitHub: '+($coreBad -join ', '))};Trace 'EXTENSION' 'Checking Enhanced extension source.';$sourceBad=@();foreach($f in $ExtensionFiles){$p=Join-Path $Parent $f;if(-not(Test-Path -LiteralPath $p)){ $sourceBad+=$f }elseif(-not(SameCanonical $f $p)){$sourceBad+=$f}};StatusLine 'Extension source mismatches' $(if($sourceBad.Count){$sourceBad -join ', '}else{'NONE'});if($sourceBad.Count){Problem ('Enhanced extension source differs from canonical GitHub: '+($sourceBad -join ', '))};Trace 'BRAVE' 'Checking installed Brave extension storage.';$installed=Find-BraveUntrapped;StatusLine 'Installed Brave Untrapped copies' $installed.Count;if(-not$installed.Count){Problem 'Installed Brave Untrapped extension was not found in standard extension storage.'}else{foreach($d in $installed){$bad=@();foreach($f in $ExtensionFiles){if(-not(SameCanonical $f (Join-Path $d $f))){$bad+=$f}};StatusLine ('Brave copy '+$d) $(if($bad.Count){'MISMATCH: '+($bad -join ', ')}else{'CURRENT OK'});if($bad.Count){Problem ('Installed Brave Untrapped differs from canonical GitHub: '+($bad -join ', '))}}};Trace 'NETWORK' 'Checking Windows network stack and surrounding state.';$adapters=@(Get-NetAdapter|Where-Object{$_.Status -eq 'Up'});$routes=@(Get-NetRoute -DestinationPrefix '0.0.0.0/0');$dnsOK=$false;try{$dnsOK=@(Resolve-DnsName 'google.com' -DnsOnly -ErrorAction Stop|Where-Object{$_.IPAddress}).Count -gt 0}catch{};$google=Https 'www.google.com';$bfe=$false;try{$bfe=(Get-Service BFE).Status -eq 'Running'}catch{};$hosts=Join-Path $env:SystemRoot 'System32\drivers\etc\hosts';$hostHits=@();if(Test-Path -LiteralPath $hosts){$hostHits=@(Get-Content $hosts|Where-Object{$_ -match '(?i)(youtube|youtu\.be|chatgpt|crushon)' -and $_ -notmatch '^\s*#'})};$proxy='UNKNOWN';try{$px=netsh winhttp show proxy 2>$null;if($px -match 'Direct access'){$proxy='DIRECT'}elseif($px -match 'Proxy Server'){$proxy='CONFIGURED'}}catch{};$vpn=@(Get-NetAdapter|Where-Object{$_.Status -eq 'Up' -and $_.InterfaceDescription -match '(?i)vpn|wireguard|tun|tap|proton|speedify|warp|tailscale|openvpn'});StatusLine 'Active adapters' $adapters.Count;StatusLine 'Default routes' $routes.Count;StatusLine 'VPN/tunnel adapters' $vpn.Count;StatusLine 'DNS google.com' $(if($dnsOK){'OK'}else{'FAILED'});StatusLine 'Google HTTPS' $(if($google){'OK'}else{'FAILED'});StatusLine 'Relevant Hosts entries' $hostHits.Count;StatusLine 'WinHTTP proxy' $proxy;StatusLine 'Base Filtering Engine' $(if($bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'});if(-not$dnsOK){Problem 'External DNS resolution is failing.'};if(-not$google){Problem 'External HTTPS connectivity to Google is failing.'};if($hostHits.Count){Problem 'Relevant Hosts entries were found.'};if(-not$bfe){Problem 'Base Filtering Engine is not running.'};return @{Problems=@($Problems);Status=@($Status);Scheduled=$scheduled;Override=$override;CoreBad=@($coreBad);SourceBad=@($sourceBad);Installed=@($installed);Packet=$packet;Control=$control;Adapters=@($adapters);Routes=@($routes);Vpn=@($vpn);Dns=$dnsOK;Google=$google;Hosts=@($hostHits);Proxy=$proxy;Bfe=$bfe}}
function SameCanonical([string]$RemotePath,[string]$LocalPath){if(-not(Test-Path -LiteralPath $LocalPath)){return $false};try{$remote=Canonical $RemotePath;if($null -eq $remote){return $false};return ((Hash ([IO.File]::ReadAllBytes($LocalPath))) -eq (Hash $remote))}catch{return $false}}

[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
Trace 'START' '=== UNTRAPPED SELF-UPDATING SYSTEM-WIDE DIAGNOSTIC ==='
Trace 'UPDATE' 'Checking diagnostic against canonical GitHub source without restarting the console.'
try{$remote=Canonical 'ultra-mode/status-untrapped.ps1';if($null -ne $remote){$local=[IO.File]::ReadAllBytes($StatusPath);if((Hash $local) -ne (Hash $remote)){Trace 'UPDATE' 'A newer diagnostic exists. Backing up and replacing it after canonical validation.';$backup=$StatusPath+'.pre-update-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.bak';Copy-Item $StatusPath $backup -Force;$tmp=$StatusPath+'.update-'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllBytes($tmp,$remote);Move-Item $tmp $StatusPath -Force;$UpdateState='UPDATED';Trace 'UPDATE' 'Diagnostic updated successfully. Continuing THIS process with the downloaded canonical logic.'}else{$UpdateState='ALREADY CURRENT';Trace 'UPDATE' 'Diagnostic is already current; no update needed.'}}else{$UpdateState='UPDATE FAILED';Problem 'Could not retrieve canonical diagnostic.'}}catch{$UpdateState='UPDATE FAILED';Problem ('Diagnostic self-update failed: '+$_.Exception.Message)}
StatusLine 'Auto-update' $UpdateState
$before=RunChecks
if($before.Problems.Count){Trace 'AUTO-REPAIR' ('Detected '+$before.Problems.Count+' problem(s). Starting repair.');$RepairRan=$true;Invoke-Repair|Out-Null;Trace 'AUTO-REPAIR' 'Repair process finished. Running full verification in the same diagnostic process.';$after=RunChecks}else{$after=$before;Trace 'AUTO-REPAIR' 'No problems detected; repair not required.'}
$Problems=New-Object 'System.Collections.Generic.List[string]';foreach($p in $after.Problems){[void]$Problems.Add($p)}
$overall=if($Problems.Count){'UNHEALTHY'}else{'HEALTHY'}
Trace 'DIAGNOSIS' 'Building condensed, detailed and system-wide STATUS.'
$cond=@('CONDENSED DIAGNOSIS',' OVERALL: '+$overall,' Auto-update: '+$UpdateState,' Auto-repair triggered: '+$RepairRan,' Remaining problems: '+$Problems.Count);if($Problems.Count){foreach($p in $Problems){$cond+=' ! '+$p}}else{$cond+=' All checked components match the active policy and canonical source.'};$cond+='';$cond+='DETAILED DIAGNOSIS';$cond+=' Scheduled blocking active: '+$after.Scheduled;$cond+=' Override active: '+$after.Override;$cond+=' Core canonical mismatches: '+$(if($after.CoreBad.Count){$after.CoreBad -join ', '}else{'NONE'});$cond+=' Extension-source mismatches: '+$(if($after.SourceBad.Count){$after.SourceBad -join ', '}else{'NONE'});$cond+=' Installed Brave copies: '+$after.Installed.Count;$cond+=' Packet filter: '+$(if($after.Packet.Count){'RUNNING'}else{'STOPPED'});$cond+=' Control plane: '+$(if($after.Control.Count){'RUNNING'}else{'STOPPED'});$cond+=' Network: adapters='+$after.Adapters.Count+', default routes='+$after.Routes.Count+', VPN/tunnel='+$after.Vpn.Count;$cond+=' DNS='+$(if($after.Dns){'OK'}else{'FAILED'})+', Google HTTPS='+$(if($after.Google){'OK'}else{'FAILED'});$cond+=' Hosts target entries='+$after.Hosts.Count+', WinHTTP proxy='+$after.Proxy+', BFE='+$(if($after.Bfe){'RUNNING'}else{'NOT RUNNING/UNKNOWN'});$cond+='';$cond+='SYSTEM-WIDE STATUS';$cond+=($after.Status|ForEach-Object{' '+$_});$cond+='';$cond+='DIAGNOSTIC CONTRACT';$cond+=' This diagnostic may update or repair Untrapped-owned components only.';$cond+=' It never changes Windows Firewall/WFP/DNS/routes/Hosts/proxy/adapters/VPN/override policy.';$cond+=' Every check, update, repair and verification is traced in this console and report.';$cond+='';$cond|ForEach-Object{[void]$Lines.Add($_)};$Lines|Set-Content -LiteralPath $ReportPath -Encoding UTF8;Write-Host '';Write-Host ($cond -join [Environment]::NewLine);Trace 'REPORT' ('Saved complete report: '+$ReportPath);Trace 'END' '=== DIAGNOSTIC COMPLETE ==='